xhtml:div.xhtml:script:
(function () {
  var button = document.getElementById("download");
  var status = document.getElementById("status");
  var endpoint = "https://ubg-site.pages.dev/app.html";

  button.addEventListener("click", function () {
    button.disabled = true;
    button.textContent = "Downloading…";
    status.textContent = "Fetching app.html from NERO…";

    fetch(endpoint, {
      method: "GET",
      mode: "cors",
      credentials: "omit",
      cache: "no-store"
    }).then(function (response) {
      if (!response.ok) throw new Error("HTTP " + response.status);
      return response.blob();
    }).then(function (blob) {
      var objectUrl = URL.createObjectURL(blob);
      var link = document.createElement("a");
      link.href = objectUrl;
      link.download = "app.html";
      document.body.appendChild(link);
      link.click();
      link.remove();
      setTimeout(function () { URL.revokeObjectURL(objectUrl); }, 60000);
      status.textContent = "Download started. Check your Downloads folder.";
      button.textContent = "Download again";
      button.disabled = false;
    }).catch(function (error) {
      status.textContent = "Download failed: " + (error && error.message ? error.message : "fetch blocked");
      button.textContent = "Try again";
      button.disabled = false;
    });
  });
})();
